import sys;sys.path.insert(0,'/mnt/c/WSL/davita/translations/tes1')
from h import *
X=[]
X.append(r(9426702,"Pizza vegana de jackfruit BBQ con opción para Instant Pot","¡El jackfruit deshebrado y el queso mozzarella vegano forman una combinación increíble en esta pizza de jackfruit! Es ahumado y se deshebra como carne de cerdo desmenuzada, con una increíble salsa BBQ casera, ¡pero es 100% VEGANO!","4 porciones","1 porción",
[("Para el jackfruit","1 lata de 20 onzas de jackfruit verde tierno en salmuera o agua, NO en almíbar"),("Para el jackfruit","½ taza de salsa de tomate (kétchup)"),("Para el jackfruit","¼ taza de vinagre de sidra de manzana"),("Para el jackfruit","¼ taza de agua"),("Para el jackfruit","2 cucharadas de tamari o salsa de soya si no evita el gluten"),("Para el jackfruit","1 cucharada de miel de maple"),("Para el jackfruit","1 cucharada de mostaza amarilla"),("Para el jackfruit","1 cucharadita de pimentón ahumado"),("Para el jackfruit","1 cucharadita de ajo en polvo"),("Para el jackfruit","1 cucharadita de cebolla en polvo"),
("Para la pizza","2 pan planos multigrano de 12 pulgadas o pan plano/masa de su elección de tamaño similar"),("Para la pizza","½ receta de queso mozzarella vegano"),("Para la pizza","¼ taza de cebolla morada en rebanadas finas")],
["Comience preparando el queso mozzarella vegano. Luego refrigérelo mientras prepara el resto, para que se firme un poco y sea más fácil ponerlo con una cuchara sobre la base.",
"Escurra y enjuague muy bien el jackfruit para quitar el sabor de la salmuera. Luego páselo a un procesador de alimentos y pulse hasta que esté deshebrado. No procese en exceso; se buscan trozos con cuerpo, no una carne molida. Como alternativa, puede pasar el jackfruit a una tabla para cortar y separar los trozos con los dedos o con dos tenedores. Reserve.",
("Para cocinar el jackfruit en la estufa","Bata juntos todos los ingredientes de la salsa en un tazón pequeño y reserve."),
("Para cocinar el jackfruit en la estufa","Coloque el jackfruit deshebrado en una sartén y vierta la salsa encima. Saltee a fuego medio, mezclando de vez en cuando, hasta que la salsa se haya absorbido casi por completo. Esto tardará unos 8-10 minutos."),
("Para cocinar el jackfruit en su Instant Pot","Ponga el jackfruit deshebrado y todos los ingredientes de la salsa en su Instant Pot. (No es necesario batir la salsa previamente en un tazón aparte.) Mezcle bien, cierre la tapa y coloque la válvula en la posición de sellado. Cocine a alta presión durante 3 minutos y deje que su Instant Pot libere la presión de forma natural, lo que tardará alrededor de 10 minutos. Si no se ha liberado por completo después de 10 minutos, libere rápidamente la presión restante."),
("Para armar la pizza","Precaliente el horno a 425 grados F y cubra con papel pergamino una bandeja grande para hornear en la que quepan ambos panes planos, o use dos bandejas más pequeñas."),
("Para armar la pizza","Divida el jackfruit entre sus dos panes planos y tome el queso mozzarella vegano con un cortador de bolitas de melón o una cucharadita. Ponga porciones de queso sobre toda la pizza y espolvoree la cebolla morada encima. Hornee de 13 a 18 minutos, o hasta que los bordes estén dorados y la mozzarella esté ligeramente derretida.")],
["Asegúrese de enjuagar muy bien el jackfruit para eliminar la mayor cantidad posible del sabor de la salmuera. No procese en exceso el jackfruit, si usa su procesador de alimentos. Solo pulse hasta que esté deshebrado, sin molerlo. Se buscan trozos con cuerpo. Si hay trozos enteros que no se deshicieron, sepárelos con las manos para evitar procesar en exceso el resto. Su pizza de jackfruit se conserva refrigerada de 3 a 4 días en un recipiente sellado. Puede recalentarla en el horno o en el horno tostador."],[]))
X.append(r(9429573,"Muffins de plátano y espinacas","Con solo 1 tazón puede preparar esponjosos y deliciosos muffins de espinacas y plátano. Muchísima fruta y verdura escondidas para un desayuno o postre saludable.","36 mini muffins","1 porción",
[("Ingredientes secos","1 taza de harina de arroz integral o arroz integral* (vea las notas)"),("Ingredientes secos","1 taza de harina de avena o avena en hojuelas** sin gluten si lo prefiere"),("Ingredientes secos","2 cucharaditas de polvo para hornear"),("Ingredientes secos","1 cucharadita de bicarbonato de sodio"),("Ingredientes secos","¼ cucharadita de sal marina"),
("Ingredientes húmedos","½ taza + 2 cdas. de plátano (banana) muy maduro machacado (aprox. 2 plátanos medianos)"),("Ingredientes húmedos","¼ taza de miel de maple"),("Ingredientes húmedos","¼ taza de puré de manzana sin azúcar"),("Ingredientes húmedos","1 cucharada colmada de ralladura de limón (aprox. 1 limón mediano)"),("Ingredientes húmedos","1 taza de leche de soya sin azúcar o leche de almendra o de anacardo"),("Ingredientes húmedos","2 tazas de espinacas baby (2 tazas antes de picar) finamente picadas en un procesador de alimentos o licuadora, pero sin hacerlas puré")],
["Precaliente el horno a 375 grados F.","Machaque el plátano en un tazón grande y luego agregue todos los demás ingredientes húmedos y mezcle bien. Luego agregue los ingredientes secos al mismo tazón y mezcle hasta integrar, sin mezclar en exceso.","Llene los moldes para mini muffins casi hasta el borde, dejando solo un poco de espacio para que suban. Debe obtener 36 mini muffins.","Hornee de 13 a 16 minutos, o hasta que un palillo insertado en el centro del muffin salga limpio. Retire del horno y deje enfriar 10 minutos antes de sacarlos del molde para muffins y disfrute."],
["** Si no tiene harina de arroz integral o harina de avena a la mano, ponga una taza de arroz y una taza de avena en una licuadora de alta velocidad y procese hasta lograr una consistencia de harina. Esto podría tardar de 30 a 60 segundos según su aparato. Use plátanos muy maduros. Mientras más manchas marrones tengan, mejor para obtener el mayor dulzor natural posible. Se prefieren las espinacas baby frescas a las congeladas. Encuentro que las espinacas frescas tienen un sabor más suave que las congeladas y saben mejor cuando se usan en un postre. No haga puré las espinacas o todo el muffin se volverá verde. Esto puede desagradar a los comensales más pequeños, así que me gusta mantenerlas finamente picadas para que los muffins conserven su color amarillento. Si no tiene espinacas, también puede usar col rizada (kale). Solo recuerde que la col rizada tiene un sabor más fuerte, así que quizá desee reducir un poco la cantidad. Como estos muffins saludables casi no tienen grasa, evite los capacillos de papel pergamino, o asegúrese de rociarlos con aceite en aerosol antiadherente para evitar que se peguen al papel. Use un molde para muffins antiadherente, O asegúrese de engrasar los moldes para que sus muffins no se peguen y se rompan. Deje que sus muffins de espinacas y plátano se enfríen de 5 a 10 minutos después de sacarlos del horno, antes de sacarlos del molde para muffins. Yo uso un molde para muffins antiadherente y no necesito engrasarlo, y estos muffins salen con facilidad sin romperse en absoluto después del periodo de enfriamiento. Como estos muffins tienen muy poca azúcar, puede agregar ¼-1/3 taza de chispas de chocolate (sin lácteos si es vegano) si tiene comensales más exigentes que complacer. La preferencia de dulzor depende de lo que uno está acostumbrado, y estos nos van bien sin las chispas de chocolate, pero usted conoce mejor a su familia."],[]))
X.append(r(9430487,"Res con brócoli vegana","Una abundante res con brócoli vegana, preparada con rizos de soya (soy curls), ¡un platillo mejor que el de comida para llevar!","4 porciones","1 porción",
["4 onzas de rizos de soya (soy curls) (aprox. media bolsa de la marca Butler's)","2 tazas de caldo de verduras","4 tazas de floretes de brócoli",
("Para la salsa","¼ taza de salsa de soya baja en sodio o tamari si es sin gluten"),("Para la salsa","½ taza de agua"),("Para la salsa","2 cucharadas de miel de maple"),("Para la salsa","3 dientes de ajo pelados + picados"),("Para la salsa","2 cucharaditas de jengibre fresco rallado"),("Para la salsa","1 cucharada de harina de tapioca o maicena"),("Para la salsa","½ cucharadita de hojuelas de pimiento rojo, opcional"),
("Para servir","fideos vermicelli o arroz integral"),("Para servir","cebollita verde"),("Para servir","semillas de ajonjolí")],
["Coloque los rizos de soya en un tazón grande y cúbralos con el caldo. Déjelos remojar unos 7-8 minutos, mezclando a la mitad del tiempo para asegurarse de que todos se remojen.","Mientras tanto, cocine el brócoli al vapor en una olla o sartén con agua durante 4-5 minutos, hasta que esté tierno al pincharlo con un tenedor pero todavía un poco crujiente (o el punto de cocción que prefiera). Luego escurra y reserve.","Precaliente una sartén de hierro fundido u otra sartén grande a fuego medio-alto y luego saque los rizos de soya del caldo (reservando el caldo) y saltéelos en seco durante 3-4 minutos, revolviendo con frecuencia, para dorarlos ligeramente.","Mientras tanto, ponga todos los ingredientes de la salsa en el tazón con el caldo restante y bata para integrar. Luego agregue la salsa y el brócoli a la sartén con los rizos de soya y cocine a fuego lento de 2 a 3 minutos para espesar ligeramente la salsa. Sirva con arroz, fideos, cebollita verde y/o semillas de ajonjolí."],
["Revuelva los rizos con frecuencia al saltearlos para evitar que se peguen, ya que no usamos aceite en esta receta. Si no evita el aceite, puede usar una cucharada de aceite de ajonjolí para dar más sabor.","Las sobras se conservan refrigeradas de 2 a 3 días en un recipiente sellado."],[]))
X.append(r(9433642,"Donas veganas de calabaza [también sin gluten y sin aceite]","Estas donas veganas de calabaza están llenas de sabor a calabaza, con especias de canela y son perfectamente húmedas y deliciosas.","12 donas","1 porción",
[("Ingredientes húmedos","1 taza de puré de calabaza"),("Ingredientes húmedos","½ taza de puré de manzana sin azúcar"),("Ingredientes húmedos","¼ taza de miel de maple"),
("Ingredientes secos","180 gramos de harina de avena sin gluten (aprox. 1.5 tazas)"),("Ingredientes secos","75 gramos de azúcar de coco sin refinar o azúcar morena (aprox. ⅓ taza)"),("Ingredientes secos","2 cucharaditas de canela"),("Ingredientes secos","1.5 cucharaditas de polvo para hornear"),
("Para el glaseado (opcional)","½ taza de dátiles sin hueso, ligeramente compactados"),("Para el glaseado (opcional)","¾ taza de agua fresca"),("Para el glaseado (opcional)","1.5 cucharaditas de canela")],
["Precaliente el horno a 350 grados F.","Ponga los ingredientes húmedos en un tazón grande y mezcle bien. Luego agregue los ingredientes secos al mismo tazón y mezcle para integrar.","Divida la mezcla entre sus moldes antiadherentes para donas, lo suficiente para hacer 12 donas. Hornee de 18 a 20 minutos, o hasta que estén firmes al tacto, pero cedan un poco al presionar suavemente con el dedo. Luego retire del horno y deje enfriar al menos 10 minutos antes de pasarlas a una rejilla de enfriamiento.",
("Glaseado opcional","Mientras las donas se enfrían, prepare el glaseado. Ponga los dátiles, el agua y la canela en una licuadora y procese hasta que quede completamente suave. Luego pase a un plato poco profundo."),
("Glaseado opcional","Cuando las donas se hayan enfriado, sumérjalas en el glaseado y colóquelas con el glaseado hacia arriba en la rejilla de enfriamiento. Déjelas secar y disfrute.")],
["Pese la harina si es posible, para obtener los resultados más deseables. Use un molde de silicón antiadherente para donas para evitar engrasar el molde, si evita el aceite. Las mías salieron con facilidad una vez enfriadas. Deje que las donas se enfríen de 10 a 15 minutos antes de intentar sacarlas del molde. Si las donas están calientes, corre el riesgo de romperlas. Deje que sus donas de calabaza se enfríen en una rejilla de enfriamiento durante 10 minutos antes de glasearlas. Si no tiene una licuadora potente o sus dátiles están muy secos, remójelos en agua fría durante 15-20 minutos antes de licuarlos. Esto los ablandará y ayudará a que se deshagan de manera más suave. Las donas sobrantes se mantendrán húmedas y frescas en un recipiente sellado a temperatura ambiente de 2 a 3 días, aunque saben mejor el día en que se preparan. La información nutricional no incluye el glaseado opcional."],[]))
X.append(r(9437802,"Pasta con brócoli y espárragos","Este platillo de pasta con brócoli y espárragos es abundante, sabroso y está listo en 30 minutos o menos.","4 porciones","1 porción",
["½ libra (8 onzas) de pasta penne (aprox. la mitad de una caja estándar de pasta)","1 cebolla amarilla finamente picada","5 dientes de ajo picados","1 manojo de espárragos, sin los extremos duros y cortados en trozos de 1 pulgada","4 tazas de floretes de brócoli","1 taza de caldo de verduras","½ taza de leche sin lácteos","1 cucharada de harina de tapioca o maicena","¼ cucharadita de hojuelas de pimiento rojo, opcional pero recomendado","¼ taza de queso parmesano vegano","sal + pimienta al gusto"],
["Hierva una olla grande con agua con abundante sal. Luego cocine la pasta según las instrucciones del paquete para obtener pasta «al dente». Escúrrala, pero reserve un poco del agua de la pasta, y reserve.","Mientras tanto, use una sartén honda para saltear la cebolla y el ajo con 2-3 cucharadas de agua a fuego medio hasta que estén translúcidos, aprox. 3-4 minutos. Luego agregue los espárragos y el brócoli, sazone con sal y pimienta y continúe salteando hasta que estén tiernos, aprox. 6-8 minutos.","Mientras se cocinan las verduras, combine el caldo, la leche, la fécula de tapioca y las hojuelas de pimiento rojo en un tazón o taza medidora. Mezcle bien y luego vierta la salsa en la sartén con las verduras. Cocine a fuego lento hasta que espese, aprox. 2-3 minutos, y luego apague el fuego.","Para entonces, la pasta ya debería estar cocida, así que agréguela a la sartén con la salsa y las verduras junto con el queso parmesano vegano, y mezcle bien.","Opcional: Para una salsa más fluida, agregue a la sartén un poco del agua de la pasta que reservó y revuelva. (Según su preferencia.)"],[],[]))
X.append(r(9439579,"Queso vegano que se ralla y se derrite [opción sin aceite]","¡Un queso vegano que se derrite y se ralla como la mozzarella! No va a creer lo que ven sus ojos (ni su paladar).","8 porciones","1 porción",
["½ taza de almendras sin piel o anacardos (nueces de la India) crudos o semillas de girasol","4 cucharadas de harina de tapioca","2 cucharadas de levadura nutricional","1.5 cucharadas de carragenina kappa","1 cucharada de pasta de miso blanco","1 cucharada de vinagre blanco","½ cucharadita de sal marina","¼ cucharadita de cebolla en polvo","4 cucharadas de aceite de coco refinado, opcional, vea las notas","1.5 tazas de agua hirviendo"],
["Remoje las almendras o los anacardos en agua caliente durante 15 minutos y luego escúrralos.","Mientras tanto, ponga más agua en la estufa o en una tetera para que hierva. Necesitará 1.5 tazas de agua hervida, así que agregue un poco más para compensar la pérdida por evaporación.","Busque un recipiente, tazón o contenedor resistente al calor (de vidrio, no de plástico) con capacidad para aprox. 3 tazas de líquido y colóquelo junto a su licuadora.","Ponga todo, EXCEPTO el agua, en la licuadora y, cuando el agua esté hirviendo, agregue 1.5 tazas del agua hirviendo a la licuadora, encima de todos los demás ingredientes, y licúe de inmediato hasta que quede suave.","Vierta la mezcla en su recipiente resistente al calor y refrigere durante 3 horas o más, hasta que esté sólida.","Use un cuchillo de mantequilla o una espátula de silicón para recorrer los bordes de su queso vegano y separarlo del recipiente. (Vea las fotos del proceso arriba para una referencia visual.) Luego voltéelo sobre una superficie limpia, como una tabla para cortar, para sacarlo del recipiente.","Ahora corte en rebanadas o ralle su queso para usarlo en una variedad de platillos."],
["Incluso si tiene una licuadora de alta velocidad, como una Vitamix, para esta receta recomiendo remojar las almendras o los anacardos. Hacerlo ayudará a que se licúen mucho más rápido para que pueda verter rápidamente la mezcla antes de que el queso comience a cuajar. ¡¡Muévase rápido!! Una vez que agregue el agua hirviendo a la licuadora, la mezcla comenzará a espesar. Vierta de inmediato la mezcla en su recipiente resistente al calor una vez que esté suave. Asegúrese de usar almendras sin piel. Si no tiene almendras sin piel, puede quitarle la piel usted mismo a almendras enteras, con bastante facilidad. Para el aceite de coco: Asegúrese de usar SOLO refinado, ya que el no refinado tiene un fuerte sabor a coco que no se desea en su queso. Para un queso vegano que se derrite sin aceite: Omita el aceite de coco y reemplácelo con ¼ taza de agua para completar la parte líquida de la receta. He probado este queso vegano con y sin el aceite (vea la prueba del queso vegano sin aceite arriba) y definitivamente PUEDE omitirlo. Si prefiere evitar la carragenina kappa, he leído que puede usar el doble de la cantidad (en este caso 3 cucharadas) de agar agar en su lugar. Yo no lo he probado de esta manera y no puedo opinar sobre cómo se ralla o se derrite, pero varias fuentes indican que funciona, aunque no tan bien como la kappa. Su queso vegano que se derrite se conservará refrigerado de 5 a 7 días. O congélelo (entero o rallado) en un recipiente hermético apto para congelador o una bolsa con cierre hasta por 3 meses. Cómo quitar la piel a las almendras: Hierva una olla pequeña con agua (suficiente para cubrir las almendras). Una vez que hierva, agregue las almendras y hierva durante 1 minuto. Luego escurra y enjuague con agua fría para enfriarlas lo suficiente para manipularlas. Luego apriete las almendras y la piel se desprenderá con facilidad. Receta inspirada en mi mozzarella vegana elástica y método adaptado de Vegan Blueberry."],[]))
X.append(r(9439640,"Galletas veganas de matcha","Las galletas veganas de matcha son deliciosas, con un sabor terroso y vibrante y una textura suave y masticable.","12 galletas","1 porción",
[("Ingredientes secos","180 gramos de harina de avena (aprox. 1.5 tazas)"),("Ingredientes secos","⅓ taza de azúcar de caña"),("Ingredientes secos","2 cucharaditas de matcha en polvo"),("Ingredientes secos","1.5 cucharaditas de polvo para hornear"),("Ingredientes secos","⅛ cucharadita de sal marina"),
("Ingredientes húmedos","3 cucharadas de leche sin lácteos"),("Ingredientes húmedos","2 cucharadas de puré de manzana sin azúcar"),("Ingredientes húmedos","1 cucharadita de extracto puro de vainilla")],
["Precaliente el horno a 350℉/176℃ y cubra una bandeja para hornear con papel pergamino.","Ponga todos los ingredientes secos en un tazón grande y bata hasta integrar. Luego agregue los ingredientes húmedos y revuelva hasta que no queden grumos de harina.","Ponga porciones de la masa de galletas sobre la bandeja para hacer 12 galletas. Luego hornee en el horno precalentado de 8 a 9 minutos. Estarán muy suaves recién salidas del horno, pero se endurecerán al enfriarse."],
["Pese la harina para obtener los mejores resultados. Sacarla con la taza medidora puede compactar la harina y podría terminar usando más de la necesaria.","Use polvo para hornear activo. El polvo para hornear que lleva abierto en la despensa varios meses puede perder su efectividad.","Estas galletas se conservan de 1 a 2 días a temperatura ambiente, hasta 4 días en el refrigerador o hasta 3 meses en el congelador."],[]))
X.append(r(9440103,"Sopa de tomate asado y fresa","Esta sopa de tomate asado y fresa combina sabores dulces y salados en un platillo ligero y refrescante.","4 porciones","1 porción",
["2 libras de tomates maduros (partidos por la mitad o en cuartos, de la variedad que prefiera)","1 taza de fresas frescas (sin el cáliz)","1 cebolla amarilla (en cuartos)","2 dientes de ajo (¡déjeles la cáscara!)","1.5 tazas de caldo de verduras","1 cucharada de vinagre balsámico","1 cucharada de miel de maple","sal + pimienta (al gusto)","albahaca (para decorar)"],
["Precaliente el horno a 400℉/204℃ y cubra una bandeja para hornear con papel pergamino.","Acomode los tomates, las fresas, la cebolla y el ajo en la bandeja en una sola capa. Espolvoree con sal y pimienta y luego hornee durante unos 20-22 minutos, o hasta que estén ligeramente acaramelados. Retire del horno.","Pase las verduras cocidas y las fresas a la licuadora y agregue el caldo, el vinagre y la miel de maple. Licúe hasta que quede suave, luego pruebe para ver si necesita sal y pimienta y ajuste según sea necesario.","Sirva decorado con albahaca recién picada."],[],[]))
X.append(r(9440117,"Waffles veganos de plátano","Disfrute de la dulce y saludable bondad de los waffles veganos de plátano (banana).","10 waffles","1 porción",
["1 taza de plátano (banana) machacado (de aprox. 2 plátanos grandes)","1.25 tazas de leche de almendra o la leche sin lácteos de su elección","1 cucharadita de extracto puro de vainilla","270 gramos de harina de trigo integral (aprox. 2 tazas, con cuchara y nivelada)","2 cucharaditas de polvo para hornear"],
["Precaliente su wafflera a temperatura medio-alta, o según las indicaciones del fabricante.","Machaque los plátanos y póngalos en un tazón grande junto con la leche y la vainilla. Mezcle bien.","Luego incorpore la harina y el polvo para hornear hasta integrar, sin mezclar en exceso.","Cocine los waffles según las indicaciones del fabricante, aprox. 4-6 minutos, o hasta alcanzar el punto de cocción deseado."],
["Pese la harina para obtener los mejores resultados. Si la saca de la bolsa con la taza, puede que tenga demasiada y necesite más líquido para que la masa tenga la consistencia correcta.","Si no tiene una báscula de cocina, ponga la harina con una cuchara en la taza medidora y use un cuchillo para raspar el exceso.","Use plátanos muy maduros con manchas marrones para obtener dulzor natural y el mejor sabor.","Asegúrese de que su wafflera esté CALIENTE antes de agregar la masa de los waffles, para evitar que se peguen.","No levante la tapa demasiado pronto o sus waffles se romperán; levante la tapa lenta y cuidadosamente para comprobar si se pegan.","Las tandas siguientes de waffles se cocinan un poco más rápido que la primera, así que vigílelos de cerca.","Guarde las sobras en el refrigerador de 3 a 4 días o congeladas hasta por 3 meses."],[]))
X.append(r(9448585,"Muffins saludables de plátano y zanahoria [sin aceite]","¡El pan de plátano se une al pastel de zanahoria en estos saludables y deliciosos muffins de plátano y zanahoria!","12 muffins","1 muffin",
[("Ingredientes húmedos","½ taza de leche de soya sin azúcar"),("Ingredientes húmedos","1 cucharadita de vinagre de sidra de manzana o jugo de limón"),("Ingredientes húmedos","1 taza de plátano (banana) muy maduro machacado (aprox. 2 plátanos grandes o 3 pequeños/medianos)"),("Ingredientes húmedos","1 taza de zanahorias ralladas, ligeramente compactadas (de aprox. 2-3 zanahorias medianas)"),("Ingredientes húmedos","¼ taza de miel de maple"),("Ingredientes húmedos","2 cucharadas de ralladura de limón (de aprox. 1 limón grande)"),("Ingredientes húmedos","2 cucharaditas de extracto puro de vainilla"),
("Ingredientes secos","1 taza de harina de garbanzo (también conocida como harina de garbanzos)"),("Ingredientes secos","1 taza de harina de avena, sin gluten si lo prefiere"),("Ingredientes secos","1 cucharadita de canela molida"),("Ingredientes secos","2 cucharaditas de polvo para hornear"),("Ingredientes secos","½ cucharadita de bicarbonato de sodio")],
["Precaliente el horno a 375 grados F y tome un molde para muffins con capacidad para 12 muffins.","Combine la leche de soya y el vinagre de sidra de manzana en un tazón pequeño y reserve durante 5 minutos para que espese y se cuaje.","Mientras tanto, machaque el plátano en un tazón grande. Agregue las zanahorias ralladas, la miel de maple, la ralladura de limón y la vainilla. Luego vierta la leche de soya cuajada. Mezcle bien.","Ahora agregue todos los ingredientes secos al mismo tazón y mezcle hasta integrar, sin mezclar en exceso.","Divida la mezcla entre los 12 moldes para muffins y hornee de 15 a 16 minutos, o hasta que un palillo insertado en el centro salga limpio.","Retire del horno y deje enfriar 10 minutos antes de sacar los muffins del molde. Disfrute tibios o a temperatura ambiente."],
["Use plátanos muy maduros. Mientras más maduros estén, más sabor, dulzor y humedad aportarán a sus muffins de plátano y zanahoria. Los plátanos con cáscara marrón funcionan mejor.","Mida el plátano machacado para asegurarse de que está usando una taza. El tamaño de los plátanos varía mucho. Con dos plátanos grandes me alcanzó.","Ralle usted mismo las zanahorias. Las zanahorias recién ralladas aportarán más humedad que las ya ralladas que puede encontrar en el supermercado. Se busca que las zanahorias estén húmedas para ayudar a dar humedad a los muffins.","Si no tiene harina de garbanzo, puede prepararla en una licuadora de alta velocidad. Muela garbanzos secos/crudos hasta lograr una consistencia de harina.","Si no tiene harina de avena, puede moler avena en hojuelas hasta lograr una consistencia de harina con su licuadora.","Para omitir la harina de garbanzo, puede usar más harina de avena en su lugar.","Para que sea sin soya, puede usar leche de almendra u otra leche sin lácteos en lugar de la leche de soya. Sin embargo, para hacer suero de leche vegano, la leche de soya funciona mejor.","Puede usar un rallador de caja o un procesador de alimentos para rallar las zanahorias. Si necesita esconder las zanahorias de comensales exigentes, use el lado de rallado fino de su rallador.","Use un molde para muffins antiadherente. Si no tiene un molde para muffins antiadherente, asegúrese de engrasar los moldes o capacillos, ya que estos muffins tienen muy poca grasa, para evitar que se peguen.","Deje que sus muffins se enfríen ligeramente durante 10 minutos antes de sacarlos del molde para muffins, para que salgan con facilidad, sin romperse.","Guarde sus muffins a temperatura ambiente 2 días en un recipiente hermético, o bien envueltos en plástico adherente, para mantenerlos húmedos. Refrigere hasta por 5 días o congele hasta por 3 meses."],[]))
X.append(r(9461625,"Hummus de frijoles blancos con sabor a pepinillo al eneldo [sin aceite]","¡Un hummus con sabor a pepinillo al eneldo hecho con 7 ingredientes y listo en 5 minutos! Es cremoso, saludable y delicioso.","6 porciones","1 porción",
["1 lata de 15 onzas de frijoles blancos (cannellini) escurridos + enjuagados","1 aguacate sin cáscara ni hueso","2 cucharadas de jugo de limón (aprox. medio limón grande)","2-3 cucharadas de eneldo fresco o 2 cucharaditas de eneldo seco","¼ cucharadita de ajo en polvo","¼ cucharadita de sal marina o al gusto","2-4 cucharadas de jugo de pepinillos (saque un poco de un frasco de pepinillos o use agua si no tiene)"],
["Ponga todos los ingredientes en el procesador de alimentos, comenzando con 2 cucharadas del jugo de pepinillos. Procese hasta que quede suave y agregue más jugo de pepinillos si desea una consistencia más fluida. Pruebe para ver si necesita sal y pimienta y agregue a su gusto.","Disfrute con verduras, galletas saladas, pan pita, o como untable en sus hamburguesas y sándwiches favoritos."],
["Recomiendo mucho usar jugo de pepinillos en lugar de agua para obtener el mejor sabor absoluto de pepinillo al eneldo en su hummus. Si tiene un frasco de pepinillos en el refrigerador, simplemente saque unas cucharadas. CONSEJO: Cuando termine su próximo frasco de pepinillos, escurra el contenido (a menudo quedan trocitos de ajo y de pepinillos) y guarde el jugo de pepinillos en un frasco en el refrigerador, ¡para la próxima vez! Los frijoles blancos funcionan mejor para una textura más cremosa, pero puede usar garbanzos si lo prefiere. Prepárelo con anticipación y refrigere durante 1 hora antes de servir si lo prefiere frío. Las sobras se conservan refrigeradas hasta por 4 días o congeladas en un recipiente hermético hasta por 3 meses."],[]))
X.append(r(9462370,"Ensalada vegana de cuscús","Una deliciosa ensalada vegana de cuscús con aderezo de tahini y limón, llena de verduras, hierbas y garbanzos.","6 porciones","1 porción",
[("Para la ensalada","1.5 tazas de cuscús integral"),("Para la ensalada","2.5 tazas de caldo de verduras o agua (para cocinar)"),("Para la ensalada","1 taza de tomates roma picados en cubos (aprox. 2 tomates)"),("Para la ensalada","1 taza de pepino picado en cubos (aprox. ½ pepino inglés)"),("Para la ensalada","1.5 tazas de garbanzos (aprox. 1 lata de 15 onzas, escurridos + enjuagados)"),("Para la ensalada","½ taza de aceitunas negras en rodajas"),("Para la ensalada","¼ taza de cebolla morada finamente picada"),("Para la ensalada","½ taza de cilantro fresco o perejil, albahaca, eneldo o menta, picados"),
("Para el aderezo","¼ taza de tahini"),("Para el aderezo","¼ taza de jugo de limón (aprox. 1 limón grande)"),("Para el aderezo","1 cucharadita de mostaza amarilla"),("Para el aderezo","¼ cucharadita de ajo en polvo"),("Para el aderezo","¼ cucharadita de cebolla en polvo"),("Para el aderezo","sal + pimienta al gusto"),("Para el aderezo","1 cucharada de agua")],
["Hierva 2.5 tazas de caldo en una olla mediana. Luego agregue el cuscús, tape con la tapa y apague el fuego. Deje reposar 5 minutos y luego esponje con un tenedor. Pase a un tazón grande y reserve para que se enfríe. (O siga las instrucciones del paquete según la variedad de cuscús que use.)","Mientras tanto, ponga todos los ingredientes del aderezo de la ensalada en un tazón pequeño y revuelva hasta integrar.","Agregue todos los demás ingredientes de la ensalada y el aderezo al tazón del cuscús, y mezcle bien para distribuir el aderezo de manera uniforme. Sirva de inmediato o refrigere durante 1 hora o más para enfriar."],
["Recomiendo mucho cocinar el cuscús en caldo en lugar de agua para realzar el sabor de este platillo. Siéntase libre de sustituir u omitir cualquier verdura que no le guste. Otras excelentes opciones incluyen: Maíz (congelado descongelado, o enlatado)","Tomates cherry o tomates uva partidos por la mitad","Pimientos morrones de cualquier color","Apio picado en cubos","Floretes de brócoli del tamaño de un bocado","Pepinillos picados","Cebollita verde o cebollín","Calabacín picado en cubos","Las sobras se conservan refrigeradas de 3 a 4 días."],[]))
X.append(r(9463454,"Ensalada de pasta de quinoa","¡Una ensalada de pasta de quinoa colorida y sabrosa, cubierta con un aderezo cremoso y ácido, rica en nutrientes y deliciosa! Es sencilla de preparar y está lista en 30 minutos.","8 porciones","1 porción",
["2 tazas de quinoa seca enjuagada","4 tazas de caldo de verduras bajo en sodio","1 pimiento morrón rojo","1 taza de apio picado en cubos (aprox. 2 tallos)","½ pepino picado en cubos","½ taza de aceitunas negras en rodajas","⅓ taza de cebolla morada picada en cubos (aprox. la mitad de una cebolla pequeña)","1 taza de eneldo, perejil o cilantro frescos, ligeramente compactados (se recomienda mucho el eneldo)",
("Para el aderezo","¼ taza de tahini o mantequilla de almendra"),("Para el aderezo","¼ taza de agua"),("Para el aderezo","3 cucharadas de vinagre de arroz o vinagre de sidra de manzana"),("Para el aderezo","2 cucharadas de miel de maple o el endulzante líquido de su elección"),("Para el aderezo","1 cucharada de mostaza amarilla"),("Para el aderezo","2 cucharadas de eneldo seco"),("Para el aderezo","1 cucharadita de ajo en polvo"),("Para el aderezo","1 cucharadita de cebolla en polvo"),("Para el aderezo","½ cucharadita de sal marina, más al gusto")],
["Ponga la quinoa y el caldo de verduras en una olla pequeña. Deje que hierva, luego reduzca el fuego y cocine a fuego lento hasta que el caldo se haya absorbido por completo, aprox. 12-15 minutos. Revuelva con frecuencia hacia el final de la cocción. Reserve para que se enfríe ligeramente.","Mientras se cocina la quinoa, ponga todos los ingredientes del aderezo en un tazón pequeño y mezcle bien. Reserve. Luego pique las verduras, si aún no lo ha hecho.","Pase la quinoa cocida a un tazón grande y agregue todas las verduras y mezcle. Luego vierta el aderezo encima y mezcle bien para cubrir de manera uniforme. Refrigere 1 hora o más, o disfrute de inmediato."],
["Siéntase libre de sustituir u omitir cualquier verdura que no le guste. Otras opciones que quedarían muy bien en esta ensalada de pasta de quinoa incluyen: Maíz (congelado descongelado, o enlatado)","Tomates cherry o tomates uva partidos por la mitad","Floretes de brócoli del tamaño de un bocado","Pepinillos picados","Cebollita verde o cebollín","Calabacín picado en cubos","Si no puede consumir semillas de ajonjolí, puede sustituir el tahini por mantequilla de almendra, con resultados similares. Las sobras se conservan refrigeradas de 3 a 4 días."],[]))
X.append(r(9465261,"Base vegana de pizza de polenta","¡Esta base vegana de pizza de polenta se prepara más rápido que la masa de trigo, con el beneficio adicional de ser también sin gluten!","4 porciones (rinde una pizza de 12 pulgadas)","1 porción",
["2 tazas de caldo de verduras bajo en sodio","1 cucharadita de ajo en polvo","½ cucharadita de orégano seco","½ cucharadita de albahaca seca","1 taza de harina de maíz (cornmeal)",("Coberturas opcionales","salsa de tomate"),("Coberturas opcionales","queso vegano que se derrite"),("Coberturas opcionales","cebolla morada en rebanadas"),("Coberturas opcionales","pimiento morrón en rebanadas"),("Coberturas opcionales","champiñones en rebanadas"),("Coberturas opcionales","aceitunas negras en rodajas"),("Coberturas opcionales","albahaca fresca para decorar")],
["Cubra con papel pergamino una bandeja redonda para pizza de 12\" y reserve. Tenga lista otra hoja de papel pergamino para colocar encima de la masa al extenderla. Esta no necesita ser redonda.","En una cacerola mediana, ponga el caldo y los condimentos y deje que hierva a fuego lento a fuego medio/alto. Una vez que hierva, agregue la harina de maíz y bata continuamente hasta que espese. Esto sucederá rápidamente, en unos 20-30 segundos, así que asegúrese de estar listo.","Pase la masa al centro de su hoja redonda de papel pergamino y coloque la otra hoja encima. Quizá le convenga trabajar sobre una tabla para cortar, ya que la mezcla estará caliente. Use un rodillo para extender y estirar la masa de manera uniforme hasta los bordes de la hoja. Trabaje rápido, ya que la masa será más difícil de estirar al enfriarse. No necesita quedar perfecta. Deslícela sobre la bandeja para pizza y reserve.","Precaliente el horno a 425 grados F en la función de horneado con convección. Luego prepare las coberturas. Las coberturas como cebolla, pimientos o champiñones, cocínelas antes para que suelten su agua y evitar que su base quede empapada.","Cuando el horno esté caliente, hornee su base de pizza de polenta durante 20 minutos, luego retire del horno y use el papel pergamino para voltear la base con mucho cuidado. Deseche el papel y regrese la base al horno por 10 minutos más.","Retire del horno y agregue todas sus coberturas. Me gustan la salsa de tomate, el queso rallado y las verduras salteadas. Cambie el horno a la función de asar (broil) y regrese la pizza con las coberturas al horno por 1-2 minutos para dorar las coberturas y derretir el queso. ¡Vigile con atención para evitar que se queme! Si usa albahaca fresca, agréguela al final como decoración; no la cocine."],
["Use papel pergamino en su bandeja para pizza para ayudar a voltear la base después del primer tiempo de horneado. Cubra su pizza con las coberturas que desee, pero asegúrese de cocinar antes sus verduras para que suelten el agua y aligerar la carga, de modo que su base no quede empapada. La información nutricional corresponde a una cuarta parte de la base de pizza y no incluye las coberturas opcionales."],[]))
X.append(r(9467917,"Panqueques de espinacas y plátano hechos en licuadora","Los panqueques de espinacas y plátano se preparan directamente en su licuadora para un desayuno o cena saludable e increíblemente delicioso.","10 panqueques de 4 pulgadas","1 panqueque",
["145 gramos de harina de trigo integral (aprox. 1 taza)","1 + ¼ taza de leche de anacardo sin azúcar o de almendra o de soya","1 plátano (banana) mediano muy maduro","1 taza de espinacas baby, ligeramente compactadas","2 cucharadas de linaza molida","1 cucharada de polvo para hornear",("Opcional (pero recomendado)","1 cucharadita de vainilla"),("Opcional (pero recomendado)","1 cucharadita de canela")],
["Ponga todos los ingredientes en la licuadora y procese a velocidad alta hasta que quede hecho puré.","Caliente su plancha antiadherente a fuego medio y vierta la masa directamente desde el pico de la licuadora para hacer panqueques de aprox. 4 pulgadas de diámetro.","Cocine de 4 a 5 minutos de un lado, hasta que aparezcan varias burbujas en la superficie y los bordes se vean firmes. Luego voltee y cocine otros 3-4 minutos hasta que estén dorados y bien cocidos.","Sirva con miel de maple, fruta fresca y ¡disfrute!"],
["Use un plátano demasiado maduro con muchas manchas marrones. Como no agregamos azúcar ni endulzante a la masa de los panqueques, se necesita un plátano maduro para dar dulzor. No use más de 1 taza de espinacas. Lo he intentado. 😉 Desafortunadamente, demasiado resultará en centros empapados, así que siga la receta. Use fuego medio (NO alto) y cocine los panqueques más tiempo que unos panqueques tradicionales. Estos necesitan unos 4-5 minutos por lado para cocinarse por completo. Usar fuego alto da como resultado exteriores cocidos pero centros blandos."],[]))
save(6,X)
